const WebSocket=require("ws"),axios=require("axios"),wss=new WebSocket.Server({port:8080});console.log("[ShellWatch Backend] WebSocket Listening on ws://localhost:8080"),wss.on("connection",ws=>{console.log("Client connected to threat stream.");const pushThreat=async(ip,domain,shellType,payload)=>{try{const geoRes=await axios.get(`http://ip-api.com/json/${ip}`),geo=geoRes.data,threatData={id:"ws_"+Date.now(),domain:domain,ip:ip,country:geo.country||"Unknown",code:geo.countryCode||"US",lat:geo.lat||0,lng:geo.lon||0,shellType:shellType,payload:payload,severity:"Critical",time:"Just now"};ws.send(JSON.stringify(threatData))}catch(e){console.error("GeoIP Resolution Error:",e)}};setInterval(()=>{pushThreat("112.198.45.101","compromised-site.com","WP","WSO WebShell v4")},5e3)});